solucao.codigo:
SENHA = "1234"
MAX_TENTATIVAS = 3

tentativas = 0
senha = ""

while senha != SENHA and tentativas < MAX_TENTATIVAS:
    senha = input("Senha: ")
    tentativas += 1
    if senha != SENHA and tentativas < MAX_TENTATIVAS:
        print(f"Senha incorreta. Restam {MAX_TENTATIVAS - tentativas} tentativa(s).")

if senha == SENHA:
    print("Acesso liberado")
else:
    print("Conta bloqueada")

valor = float(input("Valor (-1 para sair): "))

if valor == -1:
    print("Nenhum valor informado.")
else:
    maior = valor
    menor = valor
    while valor != -1:
        if valor > maior:
            maior = valor
        if valor < menor:
            menor = valor
        valor = float(input("Valor (-1 para sair): "))
    print(f"Maior: {maior} | Menor: {menor}")

saldo = 1000.0

while True:
    print("\n1 - Ver saldo\n2 - Depositar\n3 - Sacar\n4 - Sair")
    opcao = input("Opção: ").strip()

    if opcao == "1":
        print(f"Saldo: R$ {saldo:.2f}")
    elif opcao == "2":
        valor = float(input("Valor do depósito: R$ ").replace(",", "."))
        if valor <= 0:
            print("Valor inválido.")
        else:
            saldo += valor
            print(f"Depósito feito. Saldo: R$ {saldo:.2f}")
    elif opcao == "3":
        valor = float(input("Valor do saque: R$ ").replace(",", "."))
        if valor <= 0:
            print("Valor inválido.")
        elif valor > saldo:
            print("Saldo insuficiente.")
        else:
            saldo -= valor
            print(f"Saque feito. Saldo: R$ {saldo:.2f}")
    elif opcao == "4":
        print("Até logo!")
        break
    else:
        print("Opção inválida.")

n = int(input("Número: "))

if n < 2:
    primo = False
else:
    primo = True
    divisor = 2
    while divisor * divisor <= n:
        if n % divisor == 0:
            primo = False
            break
        divisor += 1

if primo:
    print(f"{n} é primo")
else:
    print(f"{n} não é primo")
